import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { toast } from 'react-toastify';
import ApiService from '../../Services/ApiService';

export default function InfluencerFollowers() {
    const navigate = useNavigate();
    const [followers, setFollowers] = useState([]);
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        loadFollowers();
    }, []);

    const loadFollowers = async () => {
        try {
            setLoading(true);
            // For now, we'll use mock data since there's no specific API for followers
            // In a real implementation, this would fetch from an actual followers API
            const mockFollowers = [
                { id: 1, name: 'Alex Johnson', email: 'alex@example.com', joinDate: '2023-01-15', avatar: null },
                { id: 2, name: 'Maria Garcia', email: 'maria@example.com', joinDate: '2023-02-20', avatar: null },
                { id: 3, name: 'James Wilson', email: 'james@example.com', joinDate: '2023-03-10', avatar: null },
                { id: 4, name: 'Sarah Davis', email: 'sarah@example.com', joinDate: '2023-04-05', avatar: null },
                { id: 5, name: 'Robert Miller', email: 'robert@example.com', joinDate: '2023-05-12', avatar: null },
            ];
            
            // Simulate API delay
            setTimeout(() => {
                setFollowers(mockFollowers);
                setLoading(false);
            }, 500);
        } catch (error) {
            console.error('Error loading followers:', error);
            toast.error('Failed to load followers: ' + (error.message || 'Unknown error'));
            setFollowers([]);
            setLoading(false);
        }
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">Followers</h4>
                    <button 
                        className="btn btn-outline-secondary"
                        onClick={() => navigate('/studio/influencer/profile')}
                    >
                        <i className="ri-arrow-left-line me-1"></i> Back to Profile
                    </button>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-body">
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border text-primary" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                                <p className="mt-2">Loading followers...</p>
                            </div>
                        ) : followers.length === 0 ? (
                            <div className="text-center py-5">
                                <i className="ri-group-line ri-3x text-muted"></i>
                                <h5 className="mt-3">No followers found</h5>
                                <p className="text-muted">You don't have any followers yet.</p>
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-centered table-nowrap mb-0">
                                    <thead className="table-light">
                                        <tr>
                                            <th>User</th>
                                            <th>Email</th>
                                            <th>Join Date</th>
                                            <th>Action</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {followers.map((follower) => (
                                            <tr key={follower.id}>
                                                <td>
                                                    <div className="d-flex align-items-center">
                                                        {follower.avatar ? (
                                                            <img 
                                                                src={follower.avatar} 
                                                                alt={follower.name} 
                                                                className="rounded-circle avatar-sm me-2"
                                                            />
                                                        ) : (
                                                            <div className="avatar-sm bg-light rounded-circle d-flex align-items-center justify-content-center me-2">
                                                                <i className="ri-user-line text-muted"></i>
                                                            </div>
                                                        )}
                                                        <div>
                                                            <h6 className="mb-0">{follower.name}</h6>
                                                        </div>
                                                    </div>
                                                </td>
                                                <td>
                                                    <a href={`mailto:${follower.email}`} className="text-primary">
                                                        {follower.email}
                                                    </a>
                                                </td>
                                                <td>
                                                    <span className="text-muted">{follower.joinDate}</span>
                                                </td>
                                                <td>
                                                    <button
                                                        type="button"
                                                        className="btn btn-sm btn-soft-primary"
                                                        onClick={() => toast.info('Message feature coming soon!')}
                                                    >
                                                        <i className="ri-message-line"></i>
                                                    </button>
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
